<?php
declare(strict_types=1);
function workflow_routes(App $a,string $path,array $b,string $method): ?array {
 if($path==='/attendance-requests'&&$method==='GET')return [200,['rows'=>$a->all('SELECT r.*,u.name,u.role,(SELECT name FROM {{users}} WHERE id=r.reviewed_by) reviewer_name FROM {{attendance_requests}} r JOIN {{users}} u ON u.id=r.user_id WHERE r.status!=\'deleted\''.($a->user['role']==='employee'?' AND r.user_id=?':'').' ORDER BY r.created_at DESC LIMIT 500',$a->user['role']==='employee'?[$a->user['id']]:[])]];
 if($path==='/attendance-requests'&&$method==='POST'){validate_correction($b);$a->assertOpen($b['time']);if($a->one("SELECT id FROM {{attendance_requests}} WHERE user_id=? AND shift=? AND type=? AND time=? AND status='pending'",[$a->user['id'],$b['shift'],$b['type'],$b['time']]))fail('Yêu cầu đã được gửi, hãy chờ quản lý xử lý.',409);if($b['shift']==='ot'&&$b['type']==='in'&&($b['ot_confirmed']??false)!==true)fail('Xác nhận bạn thực sự làm OT trước khi gửi.');$a->run('INSERT INTO {{attendance_requests}}(user_id,shift,type,time,reason,created_at) VALUES(?,?,?,?,?,?)',[$a->user['id'],$b['shift'],$b['type'],$b['time'],trim($b['reason']),now_ms()]);return [201,['id'=>(int)$a->db->lastInsertId()]];}
 if(preg_match('~^/attendance-requests/(\d+)/review$~D',$path,$m)&&$method==='POST'){$a->requireManager();$r=$a->one('SELECT * FROM {{attendance_requests}} WHERE id=?',[(int)$m[1]]);if(!$r)fail('Không tìm thấy yêu cầu.',404);if($r['status']!=='pending')fail('Yêu cầu đã được xử lý.',409);if($r['user_id']===$a->user['id'])fail('Không được tự xử lý yêu cầu của mình.',403);$target=$a->target($r['user_id']);if(!in_array($b['status']??'', ['approved','rejected'],true)||!is_string($b['note']??null)||strlen(trim($b['note']))<5||strlen($b['note'])>1500)fail('Chọn kết quả và ghi chú xử lý từ 5–500 ký tự.');$event=null;if($b['status']==='approved'){$a->assertOpen($r['time']);$all=$a->events($target['id']);$prefix=array_values(array_filter($all,fn($e)=>$e['time']<$r['time']));if($r['shift']!=='ot'){$same=array_values(array_filter($prefix,fn($e)=>$e['shift']===$r['shift']&&$e['work_date']===local_day($r['time'])));if($same&&$same[count($same)-1]['type']===$r['type'])fail('Sai thứ tự vào/ra: lượt trước đó trong ca cũng là '.($r['type']==='in'?'chấm vào':'chấm ra').'. Hãy duyệt lượt còn thiếu trước (vào lại trước rồi mới ra).',409);}$d=attendance_decision($prefix,$r['shift'],$r['time'],true);if(!empty($d['close']))fail('Hãy bổ sung lượt chấm ra Ca 2 trước khi duyệt lượt vào OT.',409);if($d['type']!==$r['type'])fail('Sai thứ tự vào/ra. Hãy bổ sung lượt còn thiếu trước.',409);$prefix[]=['type'=>$r['type'],'shift'=>$r['shift'],'time'=>$r['time'],'work_date'=>$d['workDate']];foreach($all as $e)if($e['time']>=$r['time']&&($r['shift']==='ot'||$e['shift']===$r['shift']&&$e['work_date']===local_day($r['time']))){$next=attendance_decision($prefix,$e['shift'],$e['time'],true);if($next['type']!==$e['type'])fail('Bổ sung này xung đột với lịch sử phía sau.',409);$prefix[]=$e;}$a->run("INSERT INTO {{events}}(user_id,type,time,shift,work_date,source,recorded_by,recorded_at,reason,ot_confirmed_at) VALUES(?,?,?,?,?,'manual',?,?,?,?)",[$r['user_id'],$r['type'],$r['time'],$r['shift'],$d['workDate'],$a->user['id'],now_ms(),'Bổ sung theo yêu cầu #'.$r['id'].': '.$r['reason'].' | '.$b['note'],$r['shift']==='ot'&&$r['type']==='in'?now_ms():null]);$event=(int)$a->db->lastInsertId();}$a->run('UPDATE {{attendance_requests}} SET status=?,reviewed_by=?,reviewed_at=?,review_note=?,event_id=? WHERE id=?',[$b['status'],$a->user['id'],now_ms(),trim($b['note']),$event,$r['id']]);$a->audit($r['user_id'],$b['status'].'_request');return [200,['ok'=>true]];}
 // Xóa yêu cầu bổ sung công (chủ dự án yêu cầu 08/11/2026): xóa mềm status='deleted', ẩn khỏi danh sách, không chặn chốt lương.
 // Nhân viên chỉ xóa (rút) yêu cầu của mình khi còn Chờ xử lý. Admin/Quản lý xóa mọi trạng thái; yêu cầu đã bổ sung thì gỡ luôn lượt chấm công đã thêm (công quay về như trước).
 if(preg_match('~^/attendance-requests/(\d+)/delete$~D',$path,$m)&&$method==='POST'){$r=$a->one('SELECT * FROM {{attendance_requests}} WHERE id=?',[(int)$m[1]]);if(!$r||$r['status']==='deleted')fail('Yêu cầu đã bị xóa. Tải lại.',409);$note=trim((string)($b['note']??''));if(mb_strlen($note)>500)fail('Lý do tối đa 500 ký tự.');
  if($a->user['role']==='employee'){if($r['user_id']!==$a->user['id']||$r['status']!=='pending')fail('Bạn chỉ xóa được yêu cầu của mình khi còn Chờ xử lý.',403);}
  else{$a->requireManager();$a->target($r['user_id'],true);if($r['status']==='approved'&&$r['user_id']===$a->user['id'])fail('Không được tự xóa yêu cầu đã bổ sung của mình.',403);}
  $removed=false;if($r['status']==='approved'&&$r['event_id']){$ev=$a->one('SELECT * FROM {{events}} WHERE id=? AND user_id=?',[$r['event_id'],$r['user_id']]);if($ev){attendance_event_remove($a,$ev,'Xóa yêu cầu của lượt sau trước.');$removed=true;}}
  $a->run("UPDATE {{attendance_requests}} SET status='deleted',deleted_by=?,deleted_at=?,delete_note=? WHERE id=?",[$a->user['id'],now_ms(),($removed?'[Đã gỡ lượt chấm công đã bổ sung] ':'').'Trạng thái trước: '.$r['status'].($note!==''?' | '.$note:''),$r['id']]);$a->audit($r['user_id'],'delete_request');return [200,['ok'=>true,'removed'=>$removed]];}
 // Xóa lượt chấm hộ / bổ sung (chủ dự án 09/11/2026: chấm hộ OT sai giờ không sửa được). Chỉ Admin/Quản lý, chỉ lượt nguồn manual;
 // lượt nhân viên tự chấm giữ nguyên. Yêu cầu bổ sung đã duyệt gắn với lượt này chuyển sang Đã xóa.
 if(preg_match('~^/events/(\d+)/delete$~D',$path,$m)&&$method==='POST'){$a->requireManager();$ev=$a->one('SELECT * FROM {{events}} WHERE id=?',[(int)$m[1]]);if(!$ev)fail('Lượt chấm công đã bị xóa. Tải lại.',409);
  if($ev['source']!=='manual')fail('Chỉ xóa được lượt chấm hộ / bổ sung công. Lượt nhân viên tự chấm giữ nguyên.',403);$a->target($ev['user_id'],true);if($ev['user_id']===$a->user['id'])fail('Không tự xóa lượt chấm công của mình.',403);
  $note=trim((string)($b['note']??''));if(mb_strlen($note)>500)fail('Lý do tối đa 500 ký tự.');attendance_event_remove($a,$ev,'Xóa lượt sau trước.');
  $a->run("UPDATE {{attendance_requests}} SET status='deleted',deleted_by=?,deleted_at=?,delete_note=? WHERE event_id=? AND status='approved'",[$a->user['id'],now_ms(),'[Đã xóa lượt chấm công] '.$note,$ev['id']]);$a->audit($ev['user_id'],'delete_manual_event');return [200,['ok'=>true]];}
 // Sửa giờ một lượt chấm công (chủ dự án 09/11/2026: lượt OT của Tín ghi 22:57 → 08:56 hôm sau, không trùng khách). Admin/Quản lý, mọi nguồn
 // (tự chấm giữ ảnh, GPS); bắt buộc lý do, ghi giờ cũ → mới vào lý do lượt. Ca 1/Ca 2 chỉ sửa trong cùng ngày; OT đổi được ngày. Các lượt cùng ca
 // (OT: mọi lượt OT) phải vẫn đúng thứ tự vào/ra.
 if(preg_match('~^/events/(\d+)/time$~D',$path,$m)&&$method==='POST'){$a->requireManager();$ev=$a->one('SELECT id,user_id,type,time,shift,work_date FROM {{events}} WHERE id=?',[(int)$m[1]]);if(!$ev)fail('Lượt chấm công đã bị xóa. Tải lại.',409);
  $a->target($ev['user_id'],true);if($ev['user_id']===$a->user['id'])fail('Không tự sửa giờ chấm công của mình.',403);$time=$b['time']??null;if(!is_int($time)||$time<1577836800000||$time>now_ms())fail('Chọn ngày giờ hợp lệ, không sau hiện tại.');
  $note=trim((string)($b['note']??''));if(mb_strlen($note)<5||mb_strlen($note)>500)fail('Ghi lý do sửa giờ từ 5–500 ký tự.');if($time===(int)$ev['time'])fail('Giờ mới trùng giờ cũ.');
  $a->assertOpen((int)$ev['time']);$a->assertOpen($time);$ot=$ev['shift']==='ot';if(!$ot&&local_day($time)!==$ev['work_date'])fail('Ca 1 / Ca 2 chỉ sửa giờ trong cùng ngày '.date('d/m',strtotime($ev['work_date'])).'.');
  $all=$a->events((int)$ev['user_id']);foreach($all as &$e)if((int)$e['id']===(int)$ev['id'])$e['time']=$time;unset($e);usort($all,fn($x,$y)=>[$x['time'],$x['id']]<=>[$y['time'],$y['id']]);
  $prefix=[];$work=$ev['work_date'];$hm=fn($t)=>date('H:i d/m',intdiv((int)$t,1000));
  foreach($all as $e){if($ot?$e['shift']==='ot':$e['shift']===$ev['shift']&&$e['work_date']===$ev['work_date']){try{$d=attendance_decision($prefix,$e['shift'],$e['time'],true);}catch(HttpError $x){fail('Giờ mới không hợp lệ: '.$x->getMessage(),409);}
    if($d['type']!==$e['type'])fail('Giờ mới làm sai thứ tự vào/ra (lượt '.($e['type']==='in'?'vào':'ra').' lúc '.$hm($e['time']).'). Sửa lượt kia trước, VD lượt ra trước rồi lượt vào.',409);if($ot&&(int)$e['id']===(int)$ev['id'])$work=$d['workDate'];}$prefix[]=$e;}
  $a->run('UPDATE {{events}} SET time=?,work_date=?,reason=TRIM(CONCAT(reason,?)) WHERE id=?',[$time,$work,' | Sửa giờ '.$hm($ev['time']).' → '.$hm($time).' bởi '.$a->user['name'].': '.$note,$ev['id']]);$a->audit($ev['user_id'],'edit_event_time');return [200,['ok'=>true]];}
 if($path==='/payroll/closures'&&$method==='GET'){$a->requireManager();$month=valid_month($_GET['month']??'');return [200,['rows'=>$a->all('SELECT c.id,c.month,c.closed_at,c.reopened_at,c.reopen_reason,(SELECT name FROM {{users}} WHERE id=c.closed_by) closed_by_name,(SELECT name FROM {{users}} WHERE id=c.reopened_by) reopened_by_name FROM {{payroll_closures}} c WHERE month=? ORDER BY id DESC',[$month])]];}
 if($path==='/payroll/close'&&$method==='POST'){$a->requireManager();$month=valid_month($b['month']??'');if($month>=substr(local_day(now_ms()),0,7))fail('Chỉ chốt tháng đã kết thúc.');if($a->closure($month))fail('Tháng đã được chốt.',409);$rows=$a->summaries($month);if(function_exists('payroll_apply'))$rows=payroll_apply($a,$month,$rows);foreach($rows as $p)if($p['incomplete']||$p['otIncomplete'])fail('Còn ca hoặc OT thiếu chấm ra. Xử lý đầy đủ trước khi chốt.',409);foreach($a->all("SELECT time FROM {{attendance_requests}} WHERE status='pending'") as $r)if(substr(local_day($r['time']),0,7)===$month)fail('Còn yêu cầu bổ sung chưa được xử lý.',409);$commissions=array_values(array_filter($a->all('SELECT * FROM {{commissions}}'),fn($c)=>substr(local_day($c['served_at']),0,7)===$month));$a->run('INSERT INTO {{payroll_closures}}(month,rows_json,commissions_json,closed_by,closed_at) VALUES(?,?,?,?,?)',[$month,json_encode($rows,JSON_THROW_ON_ERROR),json_encode($commissions,JSON_THROW_ON_ERROR),$a->user['id'],now_ms()]);$a->audit($a->user['id'],'close_payroll:'.$month);return [201,['ok'=>true]];}
 if($path==='/payroll/reopen'&&$method==='POST'){$a->requireAdmin();$month=valid_month($b['month']??'');if(!is_string($b['reason']??null)||strlen(trim($b['reason']))<10||strlen($b['reason'])>1500)fail('Ghi lý do mở lại từ 10–500 ký tự.');$c=$a->closure($month);if(!$c)fail('Tháng chưa được chốt.',409);$a->run('UPDATE {{payroll_closures}} SET reopened_by=?,reopened_at=?,reopen_reason=? WHERE id=?',[$a->user['id'],now_ms(),trim($b['reason']),$c['id']]);$a->audit($a->user['id'],'reopen_payroll:'.$month);return [200,['ok'=>true]];}
 return null;
}
// Gỡ một lượt chấm công: tháng chưa chốt, không phải lượt vào Làm cả ngày, các lượt phía sau cùng ca (OT: mọi lượt OT) vẫn đúng thứ tự vào/ra.
function attendance_event_remove(App $a,array $ev,string $hint): void {
 $a->assertOpen((int)$ev['time']);if($a->one('SELECT user_id FROM {{full_days}} WHERE in_event_id=?',[$ev['id']]))fail('Lượt này là lượt vào Làm cả ngày, không gỡ được.',409);
 $rest=array_values(array_filter($a->events((int)$ev['user_id']),fn($e)=>(int)$e['id']!==(int)$ev['id']));$prefix=[];
 foreach($rest as $e){if($e['time']>$ev['time']&&($ev['shift']==='ot'?$e['shift']==='ot':$e['shift']===$ev['shift']&&$e['work_date']===$ev['work_date'])&&(function()use($prefix,$e){try{return attendance_decision($prefix,$e['shift'],$e['time'],true)['type']!==$e['type'];}catch(HttpError){return true;}})())fail('Gỡ lượt '.($ev['type']==='in'?'vào':'ra').' này làm sai thứ tự vào/ra của ca (còn lượt '.($e['type']==='in'?'vào':'ra').' phía sau). '.$hint,409);$prefix[]=$e;}
 $a->run('DELETE FROM {{events}} WHERE id=?',[$ev['id']]);
}
function roster_schedule(App $a,int $id,string $day): array {$starts=[];if(function_exists('expected_shifts'))foreach(expected_shifts($a,$id,$day) as $shift=>$e){$starts[$shift]=$e['expected_at'];}return ['enabled'=>(bool)$starts,'shifts'=>array_keys($starts),'starts'=>$starts];}
function roster_routes(App $a,string $path,array $b,string $method): ?array {
 if($path!=='/roster'&&!str_starts_with($path,'/roster/'))return null;
 if($path==='/roster'&&$method==='GET'){$start=valid_day($_GET['start']??'');$end=valid_day($_GET['end']??'');$days=(strtotime($end)-strtotime($start))/86400;if($days<0||$days>61)fail('Chỉ xem tối đa 62 ngày mỗi lần.');$staff=$a->user['role']==='employee';$assignments=$a->all('SELECT a.*,u.name,u.role,u.status,u.archived,u.employee_code FROM {{shift_assignments}} a JOIN {{users}} u ON u.id=a.user_id WHERE a.day>=? AND a.day<=?'.($staff?' AND a.user_id=?':'').' ORDER BY a.day,a.shift,u.name',[$start,$end,...($staff?[$a->user['id']]:[])]);$derived=booking_roster($a,$start,$end);$assignments=array_values(array_filter($assignments,fn($r)=>!isset($derived[$r['user_id'].'_'.$r['day'].'_'.$r['shift']])));$assignments=[...$assignments,...array_values($derived)];if(function_exists('avail_roster'))$assignments=[...$assignments,...avail_roster($a,$start,$end,$staff?$a->user['id']:null,$assignments)];if(!$staff)$assignments=array_values(array_filter($assignments,fn($r)=>($r['role']??'employee')==='employee'));$people=$a->all("SELECT id,name,role,status,employee_code,department,job_title FROM {{users}} WHERE archived=0 AND status!='inactive' AND role='employee'".($staff?' AND id=?':'').' ORDER BY name',$staff?[$a->user['id']]:[]);return [200,['assignments'=>$assignments,'people'=>$people,'shifts'=>SHIFTS,'legacyImport'=>$staff?null:json_decode($a->scalar("SELECT value FROM {{roster_meta}} WHERE `key`='legacy_import'")?:'null',true)]];}
 $a->requireManager();
 if($path==='/roster/assign'&&$method==='POST'){$day=valid_day($b['day']??'');$shift=$b['shift']??'';if(!in_array($shift,['day_first','day_second'],true))fail('Chỉ phân Ca 1 hoặc Ca 2.');$ids=$b['user_ids']??[$b['user_id']??null];if(!is_array($ids)||!$ids||count($ids)>100)fail('Chọn từ 1 đến 100 nhân viên.');$ids=array_values(array_unique($ids,SORT_REGULAR));foreach($ids as $id){if(!is_int($id))fail('Nhân viên không hợp lệ.');if($a->target($id)['role']!=='employee')fail('Chỉ phân ca cho tài khoản Nhân viên.');}$created=[];foreach($ids as $id){if($a->one('SELECT id FROM {{shift_assignments}} WHERE user_id=? AND day=? AND shift=?',[$id,$day,$shift]))continue;$a->run('INSERT INTO {{shift_assignments}}(user_id,day,shift,created_by,created_at,updated_by,updated_at) VALUES(?,?,?,?,?,?,?)',[$id,$day,$shift,$a->user['id'],now_ms(),$a->user['id'],now_ms()]);$row=$a->one('SELECT * FROM {{shift_assignments}} WHERE id=?',[(int)$a->db->lastInsertId()]);roster_audit($a,'assign',null,$row);$created[]=$row;}if(!$created)fail('Nhân viên đã được phân ca này, không tạo trùng.',409);return [201,['assignments'=>$created]];}
 if(preg_match('~^/roster/(\d+)/(move|delete)$~D',$path,$m)&&$method==='POST'){$id=(int)$m[1];$old=$a->one('SELECT * FROM {{shift_assignments}} WHERE id=?',[$id]);if(!$old)fail('Phân ca đã bị xóa. Hãy tải lại lịch.',409);$a->target($old['user_id'],$m[2]==='delete');if(!is_int($b['version']??null)||$b['version']!==$old['version'])fail('Lịch đã được người khác thay đổi. Hãy tải lại trước khi sửa.',409);if($m[2]==='delete'){$a->run('DELETE FROM {{shift_assignments}} WHERE id=?',[$id]);roster_audit($a,'delete',$old,null);}else{$day=valid_day($b['day']??'');$shift=$b['shift']??'';if(!in_array($shift,['day_first','day_second'],true))fail('Ca làm không hợp lệ.');if($a->one('SELECT id FROM {{shift_assignments}} WHERE user_id=? AND day=? AND shift=? AND id!=?',[$old['user_id'],$day,$shift,$id]))fail('Nhân viên đã có trong ca đích.',409);$a->run('UPDATE {{shift_assignments}} SET day=?,shift=?,version=version+1,updated_by=?,updated_at=? WHERE id=?',[$day,$shift,$a->user['id'],now_ms(),$id]);roster_audit($a,'move',$old,$a->one('SELECT * FROM {{shift_assignments}} WHERE id=?',[$id]));}return [200,['ok'=>true]];}
 fail('Không tìm thấy chức năng phân ca.',404);
}
function roster_audit(App $a,string $action,?array $before,?array $after): void {$r=$after??$before;$a->run('INSERT INTO {{roster_audit}}(actor_id,assignment_id,user_id,action,before_json,after_json,time) VALUES(?,?,?,?,?,?,?)',[$a->user['id'],$r['id'],$r['user_id'],$action,$before?json_encode($before,JSON_THROW_ON_ERROR):null,$after?json_encode($after,JSON_THROW_ON_ERROR):null,now_ms()]);}
